#pragma once
#define WIN32_LEAN_AND_MEAN
#define NOMINMAX
#include <windows.h>
#include "provider.hpp"
#include <filesystem>
#include <fstream>
namespace mw34::m4_crt_fdiv {
struct HostRegion{std::uint64_t base{},bytes{},allocation{};unsigned state{},type{},protect{},allocation_protect{};friend bool operator==(const HostRegion&,const HostRegion&)=default;};
struct HostIdentity{std::uint64_t address{},named{},owner{},owner_named{};HostRegion region;std::wstring path;std::string sha;friend bool operator==(const HostIdentity&,const HostIdentity&)=default;};
struct ModuleIdentity{std::uint64_t handle{};HostRegion region;std::wstring path;std::string sha;friend bool operator==(const ModuleIdentity&,const ModuleIdentity&)=default;};
inline std::vector<std::byte>readfile(const std::filesystem::path&p,std::uint64_t bound){std::ifstream f(p,std::ios::binary|std::ios::ate);require(bool(f),"Input file unavailable");auto n=f.tellg();require(n>=0&&std::uint64_t(n)<=bound,"Input extent bound");std::vector<std::byte>b(static_cast<std::size_t>(n));f.seekg(0);f.read(reinterpret_cast<char*>(b.data()),b.size());require(bool(f),"Input read unavailable");return b;}
inline HostRegion region(std::uint64_t address){MEMORY_BASIC_INFORMATION m{};require(address<=UINTPTR_MAX&&VirtualQuery(reinterpret_cast<const void*>(address),&m,sizeof(m))==sizeof(m),"Actual host memory region query");return {reinterpret_cast<std::uintptr_t>(m.BaseAddress),m.RegionSize,reinterpret_cast<std::uintptr_t>(m.AllocationBase),m.State,m.Type,m.Protect,m.AllocationProtect};}
inline ModuleIdentity module_identity(HMODULE module){
    ModuleIdentity h;h.handle=reinterpret_cast<std::uintptr_t>(module);require(h.handle,"Non-null actual borrowed module required");h.region=region(h.handle);require(h.region.state==MEM_COMMIT&&h.region.type==MEM_IMAGE&&h.region.allocation==h.handle&&h.region.base==h.handle,"Actual returned module image/base owner");std::array<wchar_t,32768>path{};auto n=GetModuleFileNameW(module,path.data(),path.size());require(n&&n<path.size(),"Actual returned module path bound");h.path.assign(path.data(),n);h.sha=m4::sha256(readfile(h.path,32*1024*1024));return h;
}
inline HostIdentity host_identity(FARPROC address,HMODULE named_owner,const char*export_name){
    HostIdentity h;h.address=reinterpret_cast<std::uintptr_t>(address);h.named=reinterpret_cast<std::uintptr_t>(GetProcAddress(named_owner,export_name));require(h.address&&h.named==h.address,"Actual named Windows export target");h.region=region(h.address);require(h.region.state==MEM_COMMIT&&h.region.type==MEM_IMAGE&&!(h.region.protect&(PAGE_GUARD|PAGE_NOACCESS))&&(h.region.protect&(PAGE_EXECUTE|PAGE_EXECUTE_READ|PAGE_EXECUTE_READWRITE|PAGE_EXECUTE_WRITECOPY)),"Actual loaded executable API owner");h.owner=h.region.allocation;h.owner_named=reinterpret_cast<std::uintptr_t>(GetProcAddress(reinterpret_cast<HMODULE>(h.owner),export_name));require(h.owner_named==h.address,"Actual forwarded loaded owner named export");std::array<wchar_t,32768>path{};auto n=GetModuleFileNameW(reinterpret_cast<HMODULE>(h.owner),path.data(),path.size());require(n&&n<path.size(),"Actual host API owner path bound");h.path.assign(path.data(),n);h.sha=m4::sha256(readfile(h.path,32*1024*1024));return h;
}
struct LookupRecord{unsigned kind{},guest_token{},argument{},raw_result{},last_error{};std::uint64_t host_result{};HostIdentity before,after;ModuleIdentity module;};
// The source GetModuleHandleA handle is borrowed, never FreeLibrary'd. The
// initial gate requires stable serial loaded modules; no general loader API.
class HostServices{
    HMODULE module_{};FARPROC feature_{};HostIdentity module_api_,proc_api_,feature_identity_;ModuleIdentity module_identity_;
  public:
    [[nodiscard]] LookupRecord module(){auto kernel=GetModuleHandleW(L"kernel32.dll");require(kernel,"Loaded named KERNEL32 required");LookupRecord r;r.kind=1;r.before=host_identity(reinterpret_cast<FARPROC>(&GetModuleHandleA),kernel,"GetModuleHandleA");module_=GetModuleHandleA("KERNEL32");r.last_error=GetLastError();r.host_result=reinterpret_cast<std::uintptr_t>(module_);r.guest_token=module_?module_token:0;r.after=host_identity(reinterpret_cast<FARPROC>(&GetModuleHandleA),kernel,"GetModuleHandleA");require(r.before==r.after,"Module lookup API identity changed");if(module_){require(module_==kernel,"Actual returned named KERNEL32 module identity");r.module=module_identity(module_);module_identity_=r.module;}module_api_=r.before;return r;}
    [[nodiscard]] LookupRecord procedure(unsigned token){require(module_&&token==module_token&&GetModuleHandleA("KERNEL32")==module_,"Registry-issued actual module token required");LookupRecord r;r.kind=2;auto kernel=GetModuleHandleW(L"kernel32.dll");r.before=host_identity(reinterpret_cast<FARPROC>(&GetProcAddress),kernel,"GetProcAddress");feature_=GetProcAddress(module_,"IsProcessorFeaturePresent");r.last_error=GetLastError();r.host_result=reinterpret_cast<std::uintptr_t>(feature_);r.guest_token=feature_?feature_route:0;if(feature_)feature_identity_=host_identity(feature_,module_,"IsProcessorFeaturePresent");r.after=host_identity(reinterpret_cast<FARPROC>(&GetProcAddress),kernel,"GetProcAddress");require(r.before==r.after,"Procedure lookup API identity changed");r.module=module_identity(module_);require(r.module==module_identity_,"Issued module physical owner changed");proc_api_=r.before;return r;}
    [[nodiscard]] LookupRecord feature(unsigned token,unsigned argument){require(module_&&feature_&&token==feature_route&&argument==0&&GetModuleHandleA("KERNEL32")==module_,"Registry-issued dynamic export/feature0 required");LookupRecord r;r.kind=3;r.argument=argument;r.guest_token=token;r.before=host_identity(feature_,module_,"IsProcessorFeaturePresent");require(r.before==feature_identity_,"Actual looked-up export/owner changed");using Query=BOOL(WINAPI*)(DWORD);auto result=reinterpret_cast<Query>(feature_)(argument);r.last_error=GetLastError();r.raw_result=static_cast<unsigned>(result);r.host_result=r.raw_result;r.after=host_identity(feature_,module_,"IsProcessorFeaturePresent");require(r.before==r.after,"Actual dynamic query API identity changed");r.module=module_identity(module_);require(r.module==module_identity_,"Dynamic export issuing module physical owner changed");return r;}
};
}
